content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_break",
 "name": "Cluster Puck: intermission",
 "set": "set_ksab5_desk",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Lead anchor"
  },
  "b": {
   "mark": "b",
   "label": "Analyst"
  }
 },
 "wallText": "{status}",
 "wallSub": "KSAB5 Sports",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "jib",
    "frame": "full",
    "on": [
     "a",
     "b"
    ],
    "move": "crane",
    "cut": "dissolve"
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "hold": 2.4,
   "wall": "feed"
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Back at the desk. After the {section}, it's {away} {awayScore}, {home} {homeScore}.",
     "That's the {section} done. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "{lastGoal.name} had the last goal, at {lastGoal.clock} of the {lastGoal.period}.",
     "{goalsSaid} so far, and {lastGoal.name} has the latest."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Scoring",
     "list": "goals",
     "row": "{player}: {period} {clock}",
     "limit": 6,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "goalCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "No goals yet. {shots} shots between them and nothing to show for it.",
     "Scoreless, and {shotsHome} shots from {home} haven't changed that."
    ]
   },
   "gfx": [
    {
     "kind": "box",
     "source": "feed",
     "title": "Live: {venue}",
     "side": "right",
     "at": 0,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "goalCount",
     "op": "=",
     "value": 0
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam2",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "We've had {fightsSaid} already. {fights.0.winner} got the better of {fights.0.loser}.",
     "That's {fightsSaid} so far. It's that kind of night."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Fights",
     "list": "fights",
     "row": "{winner}: beat {loser}",
     "limit": 4,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "fightCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "That's {injuriesSaid} to the room so far. You hate to see it."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Carried off",
     "list": "injuries",
     "row": "{player}: {team}",
     "limit": 4,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "injuryCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "We'll be back for the {nextOrd}. Don't go anywhere.",
     "They're flooding the ice. Back for the {nextOrd} in a minute."
    ]
   },
   "gfx": [],
   "wall": "feed"
  }
 ]
}
